BEGIN { getline re < "re.txt" }
{
  if (match($0, re, a)) {
    out = NR " " RSTART " " RLENGTH
    for (k = 1; k <= N; k++) {
      if ((k, "start") in a) out = out " " a[k, "start"] ":" a[k, "length"]
      else out = out " -"
    }
    print out
  } else print NR " 0"
}

